{
  "commonPhenomenon": "支付订单查单响应缺失，平台仅保留处理中状态，无法确认最终交易结果。",
  "facts": [
    {
      "statement": "远端查单响应缺失，平台只保留处理中记录。",
      "evidenceIds": [
        "E-023"
      ]
    }
  ],
  "differences": [],
  "possibleExplanations": [
    {
      "hypothesis": "通道侧已完成支付但回调未送达或丢失，导致平台状态未更新。",
      "evidenceIds": [
        "E-023"
      ],
      "verification": "需通过商户订单号与通道交易号核对同一笔交易，比对通道支付时间、回调投递记录及平台入口访问日志，确认是否因网络失败、验签失败或处理失败导致未收到通知。"
    },
    {
      "hypothesis": "查单请求超时或通道返回未知状态，导致当前证据不足以确认支付结果。",
      "evidenceIds": [
        "E-023"
      ],
      "verification": "需记录查询耗时、超时阶段及通道响应摘要，确认使用的订单号与交易号，等待可用的可信查单结果或通道流水以明确最终状态。"
    },
    {
      "hypothesis": "通道侧尚未完成扣款或处理，交易仍处于进行中。",
      "evidenceIds": [
        "E-023"
      ],
      "verification": "需再次发起查单请求，若仍无响应或状态为处理中，则需结合通道接口版本和状态映射进一步核实，不能据此判断支付成功或失败。"
    }
  ],
  "checkSteps": [
    "使用商户订单号和通道交易号确认是否为同一笔交易。",
    "比对通道支付时间、回调投递记录、平台入口访问日志和商户通知应答。",
    "检查日志的时间范围、时区与保留期限，确保数据完整性。",
    "记录查询时间、耗时、超时阶段、请求关联号和通道响应摘要。",
    "确认查询使用的商户订单号与通道交易号是否正确。",
    "等待可用的可信查单结果或通道流水，并记录结果对应的时间点。",
    "遇到未知状态时，先核对通道状态映射和接口版本。"
  ],
  "missingInformation": [
    "通道侧具体的交易状态（成功/失败/处理中）。",
    "回调投递的详细日志记录（如有）。",
    "查单请求的具体超时时间和错误码。",
    "商户侧是否收到任何异步通知。"
  ],
  "knowledgeCitations": [
    "lost-callback",
    "query-timeout"
  ],
  "knowledgeOmissionReason": null
}
